" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14M13 6l6 6-6 6"/></svg></a><a class="city rv" href="/cities-we-serve/peoria-il/"><b>Peoria</b><small>Peoria County</small><svg class="ico" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14M13 6l6 6-6 6"/></svg></a><a class="city rv" href="/cities-we-serve/champaign-il/"><b>Champaign</b><small>Champaign County</small><svg class="ico" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14M13 6l6 6-6 6"/></svg></a><a class="city rv" href="/cities-we-serve/bloomington-il/"><b>Bloomington–Normal</b><small>McLean County</small><svg class="ico" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14M13 6l6 6-6 6"/></svg></a><a class="city rv" href="/cities-we-serve/elgin-il/"><b>Elgin</b><small>Kane &amp; Cook Counties</small><svg class="ico" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14M13 6l6 6-6 6"/></svg></a><a class="city rv" href="/cities-we-serve/belleville-il/"><b>Belleville</b><small>St. Clair County</small><svg class="ico" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14M13 6l6 6-6 6"/></svg></a><a class="city rv" href="/cities-we-serve/carbondale-il/"><b>Carbondale</b><small>Jackson County</small><svg class="ico" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke=